head.script:
// 호출 순번 (A : gridView calendar Column / B : 단독 InputCalendar)
scwin.callCount = { "A" : 0, "B" : 0 };
scwin.focusTimer = { "A" : null, "B" : null };

scwin.onpageload = function () {
    ica_B.setValue("20261001");
};

// A : gridView calendar Column 의 invalidMessageFunc
scwin.grd_A_cal_invalidMessageFunc = function () {
    let inputEl = document.getElementById(this.callerId + "_input");
    let rowIndex = grd_A.getFocusedRowIndex();
    scwin.callCount.A++;
    scwin.setReturnValue("[A] invalidMessageFunc 호출 " + scwin.callCount.A + " : 입력창 " + (inputEl ? inputEl.value : "")
        + " / 저장값 " + dlt_A.getCellData(rowIndex, "cal"));
    scwin.reportFocus("A", inputEl);
};

// B : 단독 InputCalendar 의 invalidMessageFunc (대조군)
scwin.ica_B_invalidMessageFunc = function () {
    let inputEl = document.getElementById(this.callerId + "_input");
    scwin.callCount.B++;
    scwin.setReturnValue("[B] invalidMessageFunc 호출 " + scwin.callCount.B + " : 입력창 " + (inputEl ? inputEl.value : ""));
    scwin.reportFocus("B", inputEl);
};

// 호출이 끝난 뒤 포커스 위치 1줄 출력
scwin.reportFocus = function (name, inputEl) {
    if (scwin.focusTimer[name]) {
        clearTimeout(scwin.focusTimer[name]);
    }
    scwin.focusTimer[name] = setTimeout(function () {
        scwin.focusTimer[name] = null;
        let focused = (inputEl !== null && document.activeElement === inputEl);
        scwin.setReturnValue("[" + name + "] 포커스 : " + (focused ? "입력창" : "입력창 밖"));
    }, 300);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
    scwin.callCount = { "A" : 0, "B" : 0 };
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
